css:
body, html {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #ff0000;
}

#game-container {
  position: relative;
  width: 80%;
  height: 80%;
  background-color: #800080;
  overflow: hidden;
}

#game-area {
  width: 100%;
  height: 100%;
  background-color: #ff6347;
}

#update-menu {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.8);
  display: flex;
  justify-content: center;
  align-items: center;
  color: white;
}

#update-content {
  background-color: #4b0082;
  padding: 20px;
  border-radius: 10px;
  text-align: center;
}

.hidden {
  display: none;
}

javascript:
var gamePaused = false;

function toggleUpdateMenu() {
  var updateMenu = document.getElementById('update-menu');
  updateMenu.classList.toggle('hidden');
  gamePaused = !gamePaused;
}

document.getElementById('resume-game').addEventListener('click', toggleUpdateMenu);

function gameLoop() {
  if (!gamePaused) {
    // Game logic here
  }
  requestAnimationFrame(gameLoop);
}

function sendDataToServer(data) {
  $.ajax({
    type: "POST",
    url: "/skibidi",
    data: JSON.stringify(data),
    contentType: "application/json",
    success: function(response) {
      console.log("Confirm and run initiated successfully:", response);
    },
    error: function(error) {
      console.error("Error initiating confirm and run:", error);
    }
  });
}

gameLoop();

